<template><AppShell :title="pageTitle"><template #default="{ can, setError }"><v-btn v-if="can('employee.manage')" block class="mb-3" prepend-icon="mdi-account-plus-outline" @click="dialog=true">직원 등록</v-btn><v-list lines="three"><v-list-item v-for="e in data.employees" :key="e.id" :title="`${e.name} (${e.employee_code})`" :subtitle="`${e.store?.name??'본사'} · ${department(e.department)} · ${e.position?.name??'-'} · ${e.role?.name}`"><template #append><v-chip size="x-small" :variant="e.employment_status==='active'?'flat':'outlined'">{{ e.employment_status }}</v-chip></template></v-list-item></v-list><v-dialog v-model="dialog" max-width="400"><v-card title="직원 등록"><v-card-text><v-text-field v-model="form.employee_code" label="사번/로그인 ID" variant="outlined"/><v-text-field v-model="form.name" label="이름" variant="outlined"/><v-text-field v-model="form.password" label="초기 비밀번호" type="password" variant="outlined"/><v-select v-model="form.department" :items="departments" label="부서" variant="outlined"/><v-select v-if="form.department!=='head_office'" v-model="form.store_id" :items="data.stores" item-title="name" item-value="id" label="점포" variant="outlined"/><v-select v-model="form.position_id" :items="data.positions" item-title="name" item-value="id" label="직급" variant="outlined"/><v-select v-model="form.role_id" :items="data.roles" item-title="name" item-value="id" label="시스템 역할" variant="outlined"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">취소</v-btn><v-btn @click="save(setError)">저장</v-btn></v-card-actions></v-card></v-dialog></template></AppShell></template>
<script setup>
import{onMounted,ref}from'vue';import AppShell from'../../components/layout/AppShell.vue';const pageTitle='직원 관리';const dialog=ref(false),data=ref({employees:[],stores:[],positions:[],roles:[]});const form=ref({employee_code:'',name:'',password:'',store_id:null,department:'kitchen',position_id:null,role_id:null});const departments=[{title:'주방',value:'kitchen'},{title:'홀',value:'hall'},{title:'본사',value:'head_office'}];const department=v=>departments.find(x=>x.value===v)?.title??v;async function load(){data.value=(await window.axios.get('/tillwhite/api/employees')).data;}async function save(err){try{await window.axios.post('/tillwhite/api/employees',form.value);dialog.value=false;await load();}catch(e){err(e.response?.data?.message??'직원 저장 실패');}}onMounted(load);
</script>
